const I=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.file}</svg>`;
const escapeHTML=(value)=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=I(el.dataset.icon));}
Object.assign(icons,{cpu:'<rect x="6" y="6" width="12" height="12" rx="3"/><path d="M9 2v4m6-4v4M9 18v4m6-4v4M2 9h4m-4 6h4m12-6h4m-4 6h4"/><rect x="9" y="9" width="6" height="6" rx="1"/>',graduation:'<path d="m2 9 10-5 10 5-10 5L2 9Zm4 2v6c4 3 8 3 12 0v-6M22 9v8"/>',external:'<path d="M14 3h7v7m-10 3L21 3M10 3H3v18h18v-7"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m3-17a3 3 0 0 1 0 6m2 4a5 5 0 0 1 2 4v3"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',list:'<path d="M9 5h12M9 12h12M9 19h12M3 5h.01M3 12h.01M3 19h.01"/>',printer:'<path d="M6 8V2h12v6M6 17H3V8h18v9h-3M6 14h12v8H6v-8M17 11h1"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18M5 6h14M5 18h14"/>',filter:'<path d="M3 4h18l-7 8v7l-4 2v-9L3 4Z"/>'});
let PRODUCT=window.RESEARCH_CONFIG.get().productTitle;
const prompts=window.PROMPT_LIBRARY||[];const lessons=window.LESSON_LIBRARY||[];
const purposes={draft:'Xây dựng kế hoạch',adapt:'Điều chỉnh thực tế',review:'Kiểm tra, hoàn thiện',materials:'Thiết kế học liệu'};
const purposeIcons={draft:'file',adapt:'sliders',review:'check-square',materials:'layers'};
const VALID_GRADES={'Tự nhiên và Xã hội':[1,2,3],'Khoa học':[4,5],'Lịch sử và Địa lí':[4,5],'Công nghệ':[3,4,5],'Tin học':[3,4,5]};
const SUBJECTS=['Toán','Tiếng Việt','Tự nhiên và Xã hội','Đạo đức','Khoa học','Lịch sử và Địa lí','Hoạt động trải nghiệm','Công nghệ','Tin học'];
const SOURCE_2345='https://thnguyentruongto.hcm.edu.vn/van-ban-cac-cap/cong-van-2345bgddt-gdth-ngay-07-thang-6-nam-2021-cua-bo-giao-duc-va-dao-tao/ct/80817/883672';
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function saveStore(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{}}
let state={page:'home',query:'',subject:'',grade:'',purpose:'',savedOnly:false,pg:1,saved:readStore('sotay-v3-saved',[]),builder:readStore('sotay-v3-builder',{}),output:readStore('sotay-v3-output',''),selected:readStore('sotay-v3-selected',null),selectedText:readStore('sotay-v3-selected-text',''),dirty:readStore('sotay-v3-dirty',false),guide:0,lessonQuery:'',lessonSubject:'',lessonGrade:'',checks:readStore('sotay-v3-checks',Array(7).fill(false)),lessonId:null};
const main=document.getElementById('main');
const E=escapeHTML;
const normalize=s=>String(s).toLocaleLowerCase('vi').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d');
const pill=(text,cls='')=>`<span class="pill ${cls}">${E(text)}</span>`;
const note=(text='AI hỗ trợ đề xuất ý tưởng và xây dựng bản dự thảo. Giáo viên kiểm tra tính chính xác, đối chiếu Chương trình GDPT 2018 và quyết định nội dung đưa vào giảng dạy.')=>`<div class="responsibility">${I('shield')}<p><strong>AI hỗ trợ. Giáo viên làm chủ.</strong> ${E(text)}</p></div>`;
const pageIntro=(label,title,desc,actions='')=>`<div class="page-heading"><div><a class="breadcrumb" href="#home">Trang bìa ${I('chevron-right')} ${E(label)}</a><h1>${title}</h1><p>${desc}</p></div>${actions}</div>`;
const options=(items,current,all)=>`<option value="">${all}</option>`+items.map(x=>`<option value="${E(x)}" ${String(current)===String(x)?'selected':''}>${E(x)}</option>`).join('');
function saveButton(id){const active=state.saved.includes(id);return `<button class="save-button ${active?'saved':''}" data-save="${id}" aria-label="${active?'Bỏ lưu':'Lưu'} câu lệnh ${id}" aria-pressed="${active}">${I('bookmark')}</button>`}
function promptCard(p){return `<article class="prompt-card"><div class="prompt-card-top"><span class="prompt-symbol ${p.purpose}">${I(purposeIcons[p.purpose])}</span>${saveButton(p.id)}</div><div class="prompt-tags">${pill(p.subject)}${pill('Lớp '+p.grade,'plain')}</div><h2>${E(p.title)}</h2><p>${E(p.desc)}</p><div class="prompt-purpose">${I(purposeIcons[p.purpose])}${E(purposes[p.purpose])}</div><div class="prompt-card-actions"><button class="text-button" data-open="${p.id}">Hướng dẫn & xem mẫu ${I('arrow-right')}</button><button class="copy-button" data-copy="${p.id}" aria-label="Sao chép câu lệnh ${E(p.title)}">${I('copy')}<span>Sao chép câu lệnh</span></button></div></article>`}
function renderHome(){const c=window.RESEARCH_CONFIG.get();return `<section class="book-cover"><div class="cover-copybook"><span class="book-research-label">${I('cpu')} SẢN PHẨM NGHIÊN CỨU KHOA HỌC</span><span class="cover-volume">SỔ TAY ĐIỆN TỬ · 2026</span><h1>${E(c.productTitle)}</h1><p class="cover-subtitlebook">Một cuốn sổ tay thực hành. Từ ý tưởng của AI đến kế hoạch bài dạy phù hợp với học sinh và điều kiện lớp học.</p><div class="cover-open-actions"><a class="button primary" href="#about">${I('book-open')} Mở sổ tay ${I('arrow-right')}</a><a class="button secondary" href="#prompts">Thư viện 80 câu lệnh</a></div><div class="cover-personbook"><div><span>NHÓM NGHIÊN CỨU</span><b>${E(c.groupName||'Đang cập nhật')}</b></div><div><span>ĐƠN VỊ THỰC HIỆN</span><b>${E(c.organization||'Đang cập nhật')}</b></div></div></div><div class="cover-visualbook"><div class="cover-orbitbook"></div><img src="assets/ai-open-book.svg" width="900" height="780" alt="Cuốn sách mở kết nối với những điểm sáng AI màu tím và cyan"><span class="cover-notechip first">${I('sparkles')} AI gợi mở ý tưởng</span><span class="cover-notechip second">${I('check-square')} Thầy cô làm chủ bài dạy</span><div class="cover-ai-signature"><strong>80 câu lệnh · 05 bước hướng dẫn · Bài dạy mẫu</strong>CÔNG NGHỆ KẾT NỐI VỚI LỚP HỌC THỰC TẾ</div></div><div class="cover-editionbook"><span>ĐỊA BÀN ỨNG DỤNG: ${E(c.applicationArea||'Đang cập nhật')}</span><a href="#admin">${I('sliders')} Chỉnh thông tin đề tài</a></div></section>`;}
function renderAbout(){const c=window.RESEARCH_CONFIG.get();return `${pageIntro('Về đề tài','Một đề tài.<br><span>Gần hơn với lớp học thực tế.</span>','Giới thiệu mục tiêu, phạm vi ứng dụng và thông tin nhóm nghiên cứu.')}<div class="about-layout"><article class="panel about-main"><span class="eyebrow">TÊN ĐẦY ĐỦ CỦA SẢN PHẨM</span><h2>${E(c.productTitle)}</h2><p class="pre-line">${E(c.introduction)}</p><h3>Tên đề tài nghiên cứu</h3><p class="pre-line">${E(c.researchTitle||'Đang cập nhật')}</p><h3>Ứng dụng tại đâu?</h3><div class="info-callout">${I('pin')}<span><strong>${E(c.applicationArea||'Địa bàn cụ thể đang cập nhật')}</strong><br>${E(c.applicationDescription)}</span></div><h3>Sổ tay đồng hành cùng giáo viên</h3><ul><li>Lựa chọn công cụ, tìm câu lệnh theo môn học, lớp và mục đích.</li><li>Đưa đặc điểm học sinh, năng lực tiếng Việt và học liệu sẵn có vào câu lệnh.</li><li>Điều chỉnh hoạt động, kiểm tra kiến thức và hoàn thiện kế hoạch trước khi dạy.</li></ul><p class="small-note">Thông tin triển khai và kết quả thực nghiệm sẽ được bổ sung theo hồ sơ chính thức của nhóm. Bản mẫu chưa thể hiện kết quả đánh giá thực nghiệm.</p></article><aside class="panel project-facts"><h2>Thông tin đề tài</h2><dl><div><dt>Nhóm nghiên cứu</dt><dd>${E(c.groupName||'Đang cập nhật')}</dd></div><div><dt>Đơn vị thực hiện</dt><dd>${E(c.organization||'Đang cập nhật')}</dd></div><div><dt>Địa bàn ứng dụng</dt><dd>${E(c.applicationArea||'Đang cập nhật')}</dd></div><div><dt>Đối tượng sử dụng</dt><dd>Giáo viên Tiểu học</dd></div><div><dt>Định hướng ưu tiên</dt><dd>Miền núi, vùng khó khăn</dd></div></dl><a class="button primary" href="#prompts">Khám phá câu lệnh ${I('arrow-right')}</a><a class="text-button" href="#admin">${I('sliders')} Chỉnh thông tin đề tài</a></aside></div>${note()}`;}
function filteredPrompts(){const q=normalize(state.query);return prompts.filter(p=>(!state.subject||p.subject===state.subject)&&(!state.grade||String(p.grade)===state.grade)&&(!state.purpose||p.purpose===state.purpose)&&(!state.savedOnly||state.saved.includes(p.id))&&normalize([p.title,p.desc,p.subject,p.grade,p.howto,...p.conditions].join(' ')).includes(q))}
function promptResults(){const list=filteredPrompts();const pages=Math.max(1,Math.ceil(list.length/12));state.pg=Math.min(state.pg,pages);const start=(state.pg-1)*12;return `<div class="results-title"><h2>${list.length} câu lệnh <span>phù hợp</span></h2><small>${list.length?`Hiển thị ${start+1}–${Math.min(start+12,list.length)} / ${list.length}`:'Thử điều chỉnh bộ lọc'}</small></div><div class="prompt-grid library-cards">${list.slice(start,start+12).map(promptCard).join('')||`<div class="empty-state">${I('search')}<h2>Chưa có mẫu phù hợp với bộ lọc</h2><p>Thử một từ khóa ngắn hơn hoặc chọn lại môn, lớp, mục đích.</p><button class="button secondary" data-reset-filters>Xóa bộ lọc</button></div>`}</div>${pages>1?`<nav class="pagination" aria-label="Phân trang câu lệnh"><button class="icon-button" data-pg="${state.pg-1}" ${state.pg===1?'disabled':''} aria-label="Trang trước">${I('arrow-left')}</button>${Array.from({length:pages},(_,i)=>`<button data-pg="${i+1}" class="${state.pg===i+1?'active':''}" ${state.pg===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')}<button class="icon-button" data-pg="${state.pg+1}" ${state.pg===pages?'disabled':''} aria-label="Trang tiếp">${I('arrow-right')}</button></nav>`:''}`}
function renderPrompts(){return `${pageIntro('Thư viện câu lệnh','Thư viện <span>80 câu lệnh AI</span>','Chọn đúng nhu cầu, bổ sung bối cảnh lớp học và sử dụng trong công cụ AI thầy cô lựa chọn.',`<span class="heading-badge">${I('layers')} 80 mẫu thực hành</span>`)}<div class="library-search">${I('search')}<input type="search" id="prompt-search" placeholder="Tìm theo tên bài, từ khóa, học liệu…" aria-label="Tìm kiếm câu lệnh" value="${E(state.query)}"><span>Gợi ý: không máy chiếu, tiếng Việt, chu vi</span></div><div class="library-layout"><aside class="panel filter-panel"><h2>${I('filter')} Lọc câu lệnh</h2><label for="filter-subject">Môn học</label><select id="filter-subject">${options(SUBJECTS,state.subject,'Tất cả môn học')}</select><label for="filter-grade">Khối lớp</label><select id="filter-grade"><option value="">Tất cả khối lớp</option>${[1,2,3,4,5].map(g=>`<option value="${g}" ${state.grade===String(g)?'selected':''}>Lớp ${g}</option>`).join('')}</select><label for="filter-purpose">Mục đích sử dụng</label><select id="filter-purpose"><option value="">Tất cả mục đích</option>${Object.entries(purposes).map(([v,t])=>`<option value="${v}" ${state.purpose===v?'selected':''}>${t}</option>`).join('')}</select><label class="checkbox-label"><input type="checkbox" id="saved-only" ${state.savedOnly?'checked':''}>Chỉ câu lệnh đã lưu</label><button class="text-button" data-reset-filters>${I('rotate')} Xóa bộ lọc</button><div class="filter-tip">${I('lightbulb')}<p>Đọc hướng dẫn, thay nội dung trong [ngoặc vuông], rồi chọn <b>Sao chép câu lệnh</b>.</p></div></aside><section id="prompt-results" aria-label="Kết quả tìm kiếm">${promptResults()}</section></div>${note('80 câu lệnh là nội dung minh họa để thực hành. Thầy cô cần bổ sung yêu cầu cần đạt và thông tin lớp học, kiểm tra đầu ra AI trước khi sử dụng.')}`}
const field=(name,label,placeholder,rows=0,required=false)=>`<div class="form-field wide"><label for="${name}">${label}${required?' <span>*</span>':''}</label>${rows?`<textarea id="${name}" name="${name}" rows="${rows}" placeholder="${placeholder}" ${required?'required':''}>${E(state.builder[name]||'')}</textarea>`:`<input type="text" id="${name}" name="${name}" placeholder="${placeholder}" value="${E(state.builder[name]||'')}" ${required?'required':''}>`}</div>`;
function selectedTemplateHTML(){const p=prompts.find(p=>p.id===state.selected);return p?`<div class="selected-template">${I('layers')}<span><small>ĐANG ÁP DỤNG MẪU</small><b>${E(p.title)}</b></span><button class="icon-button" id="clear-template" aria-label="Bỏ mẫu đã chọn">${I('x')}</button></div>`:`<a class="template-link" href="#prompts">${I('layers')} Chọn thêm mẫu từ thư viện ${I('arrow-right')}</a>`}
function outputHTML(){return state.output?`<div class="output-status ${state.dirty?'dirty':''}" id="output-status">${I(state.dirty?'info':'check')}${state.dirty?'Thông tin đã thay đổi — chọn Tạo lại để cập nhật.':'Câu lệnh đã sẵn sàng để thầy cô kiểm tra.'}</div><label class="field-label" for="builder-output">Có thể chỉnh sửa trực tiếp</label><textarea id="builder-output" rows="19">${E(state.output)}</textarea><div class="output-actions"><button class="button primary" id="copy-output">${I('copy')} Sao chép câu lệnh</button><button class="button secondary" id="download-output">${I('download')} Tải .txt</button></div><p class="small-note">Dán câu lệnh vào công cụ AI, đọc bản dự thảo và dùng danh sách kiểm tra trước khi dạy.</p><a class="text-button" href="#checklist">Mở danh sách kiểm tra ${I('arrow-right')}</a>`:`<div class="output-empty"><span>${I('sparkles')}</span><h3>Bắt đầu từ lớp học<br>của thầy cô.</h3><p>Thông tin càng rõ, câu lệnh càng giúp AI đề xuất đúng bối cảnh.</p><div><span>01 Điền thông tin</span><span>02 Tạo câu lệnh</span><span>03 Sao chép sang AI</span></div></div><button class="button secondary full" data-fill-example>${I('lightbulb')} Thử với dữ liệu minh họa</button>`}
function renderBuilder(){const b=state.builder;return `${pageIntro('Cá nhân hóa','Kế hoạch bắt đầu từ <span>lớp học thực tế.</span>','Cung cấp bối cảnh để tạo câu lệnh yêu cầu AI xây dựng, điều chỉnh hoặc rà soát bản dự thảo kế hoạch bài dạy.')}<div class="builder-layout"><form class="panel builder-form" id="builder-form"><div class="panel-heading"><span class="step-dot">01</span><div><h2>Thông tin lớp học</h2><p>Chỉ mô tả tổng hợp, không nhập danh tính học sinh.</p></div><button type="button" class="text-button" data-fill-example>Dùng ví dụ</button></div><div id="selected-template">${selectedTemplateHTML()}</div><div class="form-grid"><div class="form-field"><label for="subject">Môn học</label><select name="subject" id="subject">${SUBJECTS.map(x=>`<option ${b.subject===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label for="grade">Khối lớp</label><select id="grade" name="grade">${(VALID_GRADES[b.subject]||[1,2,3,4,5]).map(g=>`<option value="${g}" ${String(b.grade??3)===String(g)?'selected':''}>Lớp ${g}</option>`).join('')}</select></div>${field('lesson','Tên bài học','Ví dụ: Chu vi hình chữ nhật',0,true)}<div class="form-field wide"><label for="purpose">Mục đích sử dụng AI</label><select id="purpose" name="purpose">${Object.entries(purposes).map(([v,t])=>`<option value="${v}" ${(b.purpose||'draft')===v?'selected':''}>${t}</option>`).join('')}</select></div>${field('goals','Yêu cầu cần đạt và nguồn đối chiếu','Dán yêu cầu cần đạt từ tài liệu chuyên môn đang sử dụng…',3,true)}${field('studentsProfile','Đặc điểm học sinh','Kiến thức nền, tốc độ học, nhu cầu hỗ trợ, cách học quen thuộc…',2)}${field('vietnamese','Năng lực sử dụng tiếng Việt','Mức độ hiểu chỉ dẫn, diễn đạt; số em cần gợi ý từ vựng hoặc khung câu…',2)}${field('materials','Thiết bị, học liệu đang có','Bảng, phấn, thước, bìa, vật thật, học liệu địa phương…',2)}<div class="form-field"><label for="classSize">Sĩ số học sinh *</label><input type="number" id="classSize" name="classSize" min="1" max="100" value="${E(b.classSize??28)}" required></div><div class="form-field"><label for="duration">Thời lượng (phút) *</label><input type="number" id="duration" name="duration" min="5" max="180" value="${E(b.duration??35)}" required></div>${field('classroom','Điều kiện lớp học','Không gian, lớp ghép, cách bố trí bàn ghế, điều kiện kết nối…',2)}<div class="form-field wide"><span class="field-label">Lưu ý thực tế</span><div class="form-checks">${['Không máy chiếu','Internet yếu','Không máy in','Lớp ghép'].map(x=>`<label><input type="checkbox" name="constraints" value="${x}" ${(b.constraints||[]).includes(x)?'checked':''}>${x}</label>`).join('')}</div></div><div class="form-field wide" id="source-field" ${(b.purpose==='adapt'||b.purpose==='review')?'':'hidden'}><label for="source">Kế hoạch/hoạt động cần điều chỉnh, rà soát *</label><textarea name="source" id="source" rows="5" ${(b.purpose==='adapt'||b.purpose==='review')?'required':'disabled'} placeholder="Dán bản dự thảo hiện có…">${E(b.source||'')}</textarea></div></div><button class="button primary full form-submit" type="submit">${I('sparkles')} ${state.output?'Tạo lại câu lệnh cá nhân hóa':'Tạo câu lệnh cá nhân hóa'} ${I('arrow-right')}</button><p class="small-note">Bản mẫu tạo câu lệnh từ thông tin đã nhập; chưa kết nối trực tiếp dịch vụ AI.</p></form><section class="panel output-panel"><div class="panel-heading"><span class="step-dot cyan">02</span><div><h2>Câu lệnh của thầy cô</h2><p>Chỉnh sửa, sao chép và dùng trong công cụ AI.</p></div></div><div id="output-area">${outputHTML()}</div></section></div>${note()}`}
const guideSteps=[
{title:'Truy cập công cụ AI',sub:'Bắt đầu từ trang chính thức',icon:'globe',body:`<p>Thầy cô chọn một công cụ AI có thể truy cập, dùng tài khoản của mình và làm theo hướng dẫn trên trang chính thức.</p><div class="tool-links"><a href="https://chatgpt.com/" target="_blank" rel="noopener">ChatGPT ${I('external')}</a><a href="https://gemini.google.com/" target="_blank" rel="noopener">Gemini ${I('external')}</a><a href="https://copilot.microsoft.com/" target="_blank" rel="noopener">Copilot ${I('external')}</a></div><h3>Trước khi sử dụng</h3><ul><li>Kiểm tra điều kiện truy cập, chi phí và chính sách của công cụ đang dùng.</li><li>Chuẩn bị yêu cầu cần đạt và bối cảnh tổng hợp của lớp.</li><li>Nếu kết nối yếu, soạn câu lệnh trước; dùng AI lúc có mạng rồi lưu kết quả về máy.</li></ul>`,visual:['Mở trang công cụ AI','Làm theo hướng dẫn truy cập','Tạo cuộc trò chuyện mới']},
{title:'Chọn và dùng câu lệnh',sub:'Tìm đúng việc thầy cô cần',icon:'layers',body:`<p>Mở thư viện, tìm bằng từ khóa hoặc kết hợp bộ lọc môn, lớp và mục đích. Chọn <b>Hướng dẫn & xem mẫu</b> để đọc cách dùng.</p><ul><li>Thay nội dung trong [ngoặc vuông] bằng thông tin bài học.</li><li>Chọn <b>Sao chép câu lệnh</b> để dán sang công cụ AI.</li><li>Chọn <b>Cá nhân hóa theo lớp</b> nếu muốn bổ sung bối cảnh bằng biểu mẫu.</li></ul><a class="button primary" href="#prompts">Mở thư viện 80 mẫu ${I('arrow-right')}</a>`,visual:['Chọn môn · lớp · mục đích','Đọc hướng dẫn của mẫu','Thay thông tin → Sao chép']},
{title:'Cung cấp thông tin thực tế',sub:'Để gợi ý sát với lớp hơn',icon:'sliders',body:`<p>AI cần bối cảnh cụ thể, đặc biệt khi lớp có hạn chế về thiết bị hoặc học sinh cần hỗ trợ sử dụng tiếng Việt.</p><ul><li>Nhập yêu cầu cần đạt kèm nguồn để giáo viên đối chiếu.</li><li>Mô tả đặc điểm học sinh, năng lực tiếng Việt và kiến thức nền.</li><li>Liệt kê đúng học liệu, thiết bị, sĩ số, không gian và thời lượng.</li><li>Nêu những điều AI cần tránh: thiết bị không có, học liệu chưa thể chuẩn bị.</li></ul><a class="button primary" href="#builder">Nhập bối cảnh lớp ${I('arrow-right')}</a>`,visual:['28 học sinh · 35 phút','Bảng, phấn, thước, bìa','Một số em cần khung câu tiếng Việt']},
{title:'Kiểm tra bản dự thảo AI',sub:'Đối chiếu trước khi quyết định',icon:'check-square',body:`<p>Đọc toàn bộ bản dự thảo. Tự thực hiện bài tập, kiểm tra câu hỏi và đối chiếu tài liệu chuyên môn. Không dùng lời khẳng định của AI làm bằng chứng cho tính đúng đắn.</p><ul><li>Kiểm tra kiến thức, đáp án, đơn vị và yêu cầu cần đạt.</li><li>Cộng thời gian từng hoạt động, tính cả lúc chuẩn bị và chuyển nhóm.</li><li>Xem mỗi hoạt động có sản phẩm, dấu hiệu quan sát và cách hỗ trợ phù hợp hay chưa.</li></ul><a class="button primary" href="#checklist">Mở danh sách kiểm tra ${I('arrow-right')}</a>`,visual:['Đối chiếu yêu cầu cần đạt','Tự kiểm tra ví dụ và đáp án','Rà thời lượng, học liệu, sự tham gia']},
{title:'Chỉnh sửa và lưu sử dụng',sub:'Giáo viên hoàn thiện kế hoạch',icon:'file',body:`<p>Yêu cầu AI sửa phần cụ thể chưa phù hợp; giữ yêu cầu cần đạt đã xác định. Thầy cô chọn phương án có thể thực hiện và tự hoàn thiện kế hoạch.</p><ul><li>Thay hoạt động cần thiết bị bằng vật thật, bảng hoặc nhiệm vụ trong vở.</li><li>Bổ sung chỉ dẫn ngắn, thao tác làm mẫu hoặc khung câu tiếng Việt.</li><li>Lưu bản đã kiểm tra trước giờ dạy; ghi lại điều chỉnh sau tiết học.</li></ul><a class="button primary" href="#lessons">Xem bài dạy tham khảo ${I('arrow-right')}</a>`,visual:['Chỉ rõ phần cần thay đổi','Điều chỉnh theo điều kiện thực tế','Giáo viên duyệt → Lưu → Rút kinh nghiệm']}
];
function guideVisual(g,i){return `<div class="guide-visual" aria-label="Minh họa quy trình bước ${i+1}"><span class="visual-caption">MINH HỌA QUY TRÌNH</span><div class="visual-window"><div class="window-bar"><i></i><i></i><i></i><span>Bước 0${i+1}</span></div><span class="window-icon">${I(g.icon)}</span>${g.visual.map((s,k)=>`<div class="visual-step"><b>${k+1}</b><span>${s}</span>${I('check')}</div>`).join('')}</div><span class="visual-footnote">Mô phỏng thao tác · Không phải giao diện công cụ AI cụ thể</span></div>`}
function renderGuide(){const g=guideSteps[state.guide];return `${pageIntro('Hướng dẫn','Cùng thầy cô thực hành <span>từng bước.</span>','Từ mở công cụ AI đến hoàn thiện kế hoạch. Có thể quay lại bất kỳ bước nào khi cần.')}<div class="guide-layout"><aside class="panel guide-nav"><span class="eyebrow">05 BƯỚC SỬ DỤNG</span>${guideSteps.map((x,i)=>`<button data-guide="${i}" class="${state.guide===i?'active':''}" ${state.guide===i?'aria-current="step"':''}><span>0${i+1}</span><div><b>${x.title}</b><small>${x.sub}</small></div></button>`).join('')}<a href="#resources" class="text-button">${I('download')} Tải hướng dẫn mẫu</a></aside><article class="panel guide-article"><span class="eyebrow">BƯỚC 0${state.guide+1} / 05</span><h2>${g.title}</h2><div class="guide-article-grid"><div class="prose">${g.body}</div>${guideVisual(g,state.guide)}</div><div class="guide-controls"><button class="button secondary" data-guide="${state.guide-1}" ${state.guide===0?'disabled':''}>${I('arrow-left')} Trước</button><span>${state.guide+1} / 5</span><button class="button primary" data-guide="${state.guide+1}" ${state.guide===4?'disabled':''}>Bước tiếp theo ${I('arrow-right')}</button></div></article></div>${note()}`}
const checks=[['Đối chiếu yêu cầu cần đạt','Dựa vào Chương trình GDPT 2018 và tài liệu đang sử dụng; không nhận yêu cầu do AI tự suy diễn.'],['Kiểm tra cấu trúc kế hoạch','Xem mục tiêu, thiết bị/học liệu, các hoạt động dạy học và điều chỉnh sau bài dạy theo hướng dẫn chuyên môn áp dụng tại đơn vị.'],['Tự kiểm tra kiến thức và đáp án','Tính lại phép tính, đơn vị, dữ kiện, ví dụ và lời giải; đánh dấu điều cần xác minh.'],['Rà soát thời lượng và tổ chức','Tính cả lúc chuyển nhóm, phát học liệu; mỗi hoạt động có nhiệm vụ và sản phẩm rõ.'],['Đối chiếu thiết bị, học liệu thực có','Không phụ thuộc vào máy chiếu, máy in hoặc Internet khi lớp không đáp ứng.'],['Xem mức hỗ trợ tiếng Việt','Chỉ dẫn vừa sức, có thao tác làm mẫu, từ khóa hoặc khung câu phù hợp khi cần.'],['Giáo viên hoàn thiện và quyết định','Chọn phương án phù hợp, ghi chỗ còn cần điều chỉnh và chịu trách nhiệm nội dung đưa vào lớp.']];
function renderChecklist(){const count=state.checks.filter(Boolean).length;return `${pageIntro('Kiểm tra kế hoạch','Một lượt kiểm tra,<br><span>thêm sự chủ động trước giờ dạy.</span>','Dùng sau khi nhận bản dự thảo AI hoặc chỉnh sửa một kế hoạch tham khảo.')}<div class="checklist-layout"><section class="panel checklist-items">${checks.map(([title,desc],i)=>`<label class="check-item"><input type="checkbox" data-check="${i}" ${state.checks[i]?'checked':''}><span><b>${title}</b><p>${desc}</p></span></label>`).join('')}</section><aside class="panel progress-panel"><span class="eyebrow">TIẾN ĐỘ TỰ RÀ SOÁT</span><div class="progress-ring" style="--progress:${count/7*100}%"><div><b>${count}<small>/7</small></b><span>NỘI DUNG ĐÃ KIỂM TRA</span></div></div><h2>${count===7?'Đã đánh dấu đủ 7 nội dung':'Từng bước để yên tâm hơn'}</h2><p>Việc đánh dấu không thay thế thẩm định chuyên môn. Thầy cô tiếp tục xác minh những điểm còn băn khoăn.</p><button class="button primary full" id="download-checklist">${I('download')} Tải danh sách .txt</button><button class="text-button" id="reset-checklist">${I('rotate')} Bắt đầu kiểm tra lại</button></aside></div>${note()}`}
function lessonCard(l){return `<article class="lesson-card"><div class="lesson-art"><span class="lesson-subject-icon">${I(l.subject==='Toán'?'grid':l.subject==='Tiếng Việt'?'book-open':l.subject==='Tự nhiên và Xã hội'?'leaf':l.subject==='Đạo đức'?'users':'sprout')}</span><span class="lesson-art-label">KẾ HOẠCH THAM KHẢO</span><div class="lesson-paper-lines"></div>${pill(l.duration+' phút','plain')}</div><div class="lesson-card-body"><div class="prompt-tags">${pill(l.subject)}${pill('Lớp '+l.grade,'plain')}</div><h2><a href="#lesson/${l.id}">${E(l.title)}</a></h2><p>${E(l.summary)}</p><div class="lesson-condition">${I('pin')} ${E(l.conditions[0]||'Điều chỉnh theo thực tế')}</div><a class="text-button" href="#lesson/${l.id}">Xem kế hoạch & học liệu ${I('arrow-right')}</a></div></article>`}
function lessonResults(){const q=normalize(state.lessonQuery);const list=lessons.filter(l=>(!state.lessonSubject||l.subject===state.lessonSubject)&&(!state.lessonGrade||String(l.grade)===state.lessonGrade)&&normalize(l.title+' '+l.summary+' '+l.subject+' '+l.conditions.join(' ')).includes(q));return `<div class="results-title"><h2>${list.length} kế hoạch tham khảo</h2><span class="small-note">Nội dung minh họa · Chưa thẩm định chuyên môn</span></div><div class="lesson-grid">${list.map(lessonCard).join('')||`<div class="empty-state">${I('search')}<h2>Chưa có bài phù hợp bộ lọc</h2><p>Thử đổi từ khóa, môn hoặc khối lớp.</p><button class="button secondary" id="reset-lessons">Xóa bộ lọc</button></div>`}</div>`}
function renderLessons(){return `${pageIntro('Kho bài dạy','Kế hoạch tham khảo.<br><span>Gợi ý để thầy cô điều chỉnh.</span>','Các mẫu được tổ chức theo hướng mục tiêu, thiết bị/học liệu, hoạt động dạy học và điều chỉnh sau bài dạy.')}<div class="source-callout">${I('book-open')}<p><strong>Định hướng tham khảo Công văn 2345/BGDĐT-GDTH ngày 07/06/2021.</strong> Giáo viên đối chiếu hướng dẫn chuyên môn và điều kiện đơn vị trước khi sử dụng. <a href="${SOURCE_2345}" target="_blank" rel="noopener">Xem nguồn ${I('external')}</a></p></div><div class="lesson-toolbar"><div class="search-box">${I('search')}<input type="search" id="lesson-search" aria-label="Tìm bài dạy mẫu" placeholder="Tìm tên bài, học liệu, điều kiện…" value="${E(state.lessonQuery)}"></div><select id="lesson-subject" aria-label="Lọc môn bài dạy">${options([...new Set(lessons.map(l=>l.subject))],state.lessonSubject,'Tất cả môn học')}</select><select id="lesson-grade" aria-label="Lọc khối bài dạy"><option value="">Tất cả khối lớp</option>${[1,2,3,4,5].map(g=>`<option value="${g}" ${state.lessonGrade===String(g)?'selected':''}>Lớp ${g}</option>`).join('')}</select></div><section id="lesson-results">${lessonResults()}</section>${note()}`}
function listHTML(items){return `<ul>${items.map(x=>`<li>${E(x)}</li>`).join('')}</ul>`}
function lessonText(l){return `${PRODUCT}\nKẾ HOẠCH MINH HỌA — CẦN GIÁO VIÊN KIỂM TRA\n\n${l.title}\n${l.subject} — Lớp ${l.grade} — ${l.duration} phút\n\nI. YÊU CẦU CẦN ĐẠT (MINH HỌA, CẦN GIÁO VIÊN ĐỐI CHIẾU)\n${l.goals}\n\nII. ĐỒ DÙNG DẠY HỌC\n${l.materials.join('\n')}\n\nIII. CÁC HOẠT ĐỘNG DẠY HỌC CHỦ YẾU\n${l.activities.map((a,i)=>`${i+1}. ${a.name} — ${a.minutes} phút\nGiáo viên: ${a.teacher}\nHọc sinh: ${a.students}\nDấu hiệu/sản phẩm: ${a.evidence}`).join('\n\n')}\n\nPHIẾU HỌC TẬP & GỢI Ý CHO GV\n${l.worksheet}\n\nCÂU HỎI GỢI Ý\n${l.questions.join('\n')}\n\nĐIỀU CHỈNH THEO THỰC TẾ\n${l.adaptations.join('\n')}\n\nKIỂM TRA TRƯỚC KHI SỬ DỤNG\n${l.review.join('\n')}\n\nIV. ĐIỀU CHỈNH SAU BÀI DẠY (NẾU CÓ)\n${readStore('sotay-v3-notes',{})[l.id]||'Giáo viên bổ sung sau khi dạy: ................................'}`}
function renderLesson(){const l=lessons.find(x=>x.id===state.lessonId);if(!l)return `${pageIntro('Kho bài dạy','Không tìm thấy kế hoạch','Mời thầy cô quay lại kho bài dạy để chọn mẫu.')}<a class="button primary" href="#lessons">Mở kho bài dạy</a>`;return `<a class="breadcrumb" href="#lessons">${I('arrow-left')} Kho bài dạy mẫu</a><div class="lesson-detail-heading"><div><div class="prompt-tags">${pill(l.subject)}${pill('Lớp '+l.grade,'plain')}${pill(l.duration+' phút','cyan')}</div><h1>${E(l.title)}</h1><p>${E(l.summary)}</p></div><div><button class="button primary" data-adapt-lesson="${l.id}">${I('sliders')} Điều chỉnh cho lớp tôi</button><button class="button secondary" data-print-lesson="${l.id}">${I('printer')} In / lưu PDF</button></div></div><div class="source-callout">${I('info')}<p>Đây là kế hoạch minh họa để tham khảo cấu trúc và cách tổ chức. Giáo viên đối chiếu yêu cầu cần đạt, kiểm tra kiến thức và điều kiện thực hiện trước khi dùng.</p></div><div class="lesson-detail-layout"><article class="panel lesson-content"><section><span class="section-index">01</span><h2>Yêu cầu cần đạt — minh họa, cần GV đối chiếu</h2><p class="pre-line">${E(l.goals)}</p></section><section><span class="section-index">02</span><h2>Đồ dùng dạy học</h2>${listHTML(l.materials)}</section><section><span class="section-index">03</span><h2>Các hoạt động dạy học chủ yếu</h2><div class="activity-list">${l.activities.map((a,i)=>`<article class="activity"><div class="activity-heading"><span>${i+1}</span><h3>${E(a.name)}</h3>${pill(a.minutes+' phút','plain')}</div><dl><div><dt>Giáo viên</dt><dd>${E(a.teacher)}</dd></div><div><dt>Học sinh</dt><dd>${E(a.students)}</dd></div><div><dt>Sản phẩm / dấu hiệu quan sát</dt><dd>${E(a.evidence)}</dd></div></dl></article>`).join('')}</div></section><section><span class="section-index">HỌC LIỆU KÈM THEO</span><h2>Phiếu học tập và gợi ý</h2><p class="small-note">Tách phần đáp án/gợi ý dành cho giáo viên trước khi sử dụng phiếu với học sinh.</p><pre class="worksheet">${E(l.worksheet)}</pre><button class="button secondary" data-copy-worksheet="${l.id}">${I('copy')} Sao chép phiếu học tập</button></section><section><h2>Câu hỏi gợi ý</h2>${listHTML(l.questions)}</section><section><h2>Kiểm tra trước khi sử dụng</h2>${listHTML(l.review)}</section><section><span class="section-index">04</span><h2>Điều chỉnh sau bài dạy (nếu có)</h2><label class="field-label" for="lesson-reflection">Giáo viên ghi sau khi tổ chức dạy học</label><textarea id="lesson-reflection" data-lesson-note="${l.id}" rows="4" placeholder="Điều đã phù hợp, khó khăn quan sát được, nội dung hoặc cách tổ chức cần điều chỉnh…">${E(readStore('sotay-v3-notes',{})[l.id]||'')}</textarea><p class="small-note">Ghi chú chỉ lưu trên trình duyệt này. Để giữ bản đầy đủ, thầy cô chọn Tải kế hoạch .txt.</p></section></article><aside><div class="panel adaptation-panel"><span class="feature-icon">${I('pin')}</span><h2>Điều chỉnh cho điều kiện vùng cao</h2>${listHTML(l.adaptations)}<div class="mini-divider"></div><h3>Trước khi sử dụng</h3><p>Đối chiếu nội dung mẫu với Chương trình GDPT 2018, tài liệu đang dùng và hướng dẫn chuyên môn tại đơn vị.</p><a class="text-button" href="#checklist">Mở danh sách kiểm tra ${I('arrow-right')}</a></div><button class="button secondary full" data-download-lesson="${l.id}">${I('download')} Tải kế hoạch .txt</button></aside></div>${note()}`}
function renderResources(){const saved=prompts.filter(p=>state.saved.includes(p.id));return `${pageIntro('Tài liệu','Lưu lại để <span>thực hành khi cần.</span>','Bản PDF và Word minh họa tên, cấu trúc, hướng dẫn sử dụng và kiểm tra. Thư viện đầy đủ 80 câu lệnh nằm trên website.')}<div class="download-grid"><article class="panel download-card"><span class="file-tile">PDF</span><div><h2>Hướng dẫn minh họa</h2><p>Bản trình bày để đọc và góp ý cấu trúc.</p><a href="assets/so-tay-ai-v3.pdf" download="So_tay_dien_tu_AI_Ban_minh_hoa.pdf" class="button primary">${I('download')} Tải PDF</a></div></article><article class="panel download-card"><span class="file-tile cyan">DOCX</span><div><h2>Bản có thể chỉnh sửa</h2><p>Tài liệu Word đồng bộ với cấu trúc mới.</p><a href="assets/so-tay-ai-v3.docx" download="So_tay_dien_tu_AI_Ban_minh_hoa.docx" class="button secondary">${I('download')} Tải Word</a></div></article></div><div class="resource-library panel"><span class="feature-icon">${I('layers')}</span><div><h2>Mang theo thư viện 80 câu lệnh</h2><p>Tải bản văn bản để đọc, chỉnh nội dung trong ngoặc và chuẩn bị khi kết nối mạng hạn chế.</p></div><button class="button secondary" id="download-prompts">${I('download')} Tải 80 mẫu .txt</button></div><div class="section-heading saved-heading"><div><span class="eyebrow">GÓC THỰC HÀNH</span><h2>Câu lệnh đã lưu <span class="count-badge">${saved.length}</span></h2></div><a class="text-button" href="#prompts">Mở thư viện ${I('arrow-right')}</a></div><div class="prompt-grid">${saved.map(promptCard).join('')||`<div class="empty-state">${I('bookmark')}<h2>Chưa có câu lệnh được lưu</h2><p>Thầy cô dùng biểu tượng đánh dấu trong thư viện để lưu mẫu cần dùng lại.</p><a class="button primary" href="#prompts">Khám phá thư viện</a></div>`}</div>${note()}`}
const pages={home:['Trang bìa',renderHome],about:['Về đề tài',renderAbout],prompts:['80 câu lệnh AI',renderPrompts],builder:['Cá nhân hóa kế hoạch',renderBuilder],guide:['Hướng dẫn từng bước',renderGuide],lessons:['Kho bài dạy mẫu',renderLessons],lesson:['Kế hoạch tham khảo',renderLesson],checklist:['Kiểm tra kế hoạch',renderChecklist],resources:['Tài liệu tải xuống',renderResources],admin:['Quản trị đề tài',()=>window.SOTAY_ADMIN.render()]};
function render(){PRODUCT=window.RESEARCH_CONFIG.get().productTitle;main.className=state.page==='home'?'home-page':'wrap page-wrap';main.innerHTML=pages[state.page][1]();document.querySelectorAll('nav a[data-page]').forEach(a=>{const active=a.dataset.page===state.page||(state.page==='lesson'&&a.dataset.page==='lessons');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});hydrateIcons(main);window.Handbook.rendered(state.page);if(state.page==='admin')window.SOTAY_ADMIN.mount();document.title=state.page==='home'?PRODUCT:pages[state.page][0]+' — Sổ tay điện tử AI'}
function closeMenu(){const d=document.getElementById('drawer');d.classList.remove('open');d.inert=true;document.getElementById('scrim').classList.remove('visible');document.getElementById('menu-toggle').setAttribute('aria-expanded','false')}
function route(){const hash=location.hash.slice(1)||'home';if(hash.startsWith('lesson/')){state.page='lesson';state.lessonId=decodeURIComponent(hash.slice(7))}else state.page=pages[hash]?hash:'home';render();closeMenu();window.scrollTo({top:0,behavior:'instant'})}
function go(page){if(location.hash==='#'+page){state.page=page;render();window.scrollTo({top:0,behavior:'instant'})}else window.Handbook.turn('#'+page)}
let toastTimer;function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3500)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Đã sao chép. Thầy cô có thể dán và chỉnh sửa.')}catch{const t=document.createElement('textarea');t.value=text;t.style.cssText='position:fixed;opacity:0';document.body.append(t);t.select();let ok=false;try{ok=document.execCommand('copy')}catch{}t.remove();toast(ok?'Đã sao chép.':'Hãy chọn nội dung và nhấn Ctrl/Cmd + C để sao chép.')}}
function download(name,text,type='text/plain;charset=utf-8'){const a=document.createElement('a');const url=URL.createObjectURL(new Blob(['\uFEFF'+text],{type}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function openPrompt(id){const p=prompts.find(x=>x.id===id);if(!p)return;document.getElementById('prompt-dialog').dataset.prompt=id;document.getElementById('dialog-title').textContent=p.title;document.getElementById('dialog-tags').innerHTML=pill(p.subject)+pill('Lớp '+p.grade,'plain')+pill(purposes[p.purpose],'cyan');document.getElementById('dialog-howto').textContent=p.howto;document.getElementById('dialog-text').value=p.text;document.getElementById('prompt-dialog').showModal()}
function persistBuilder(){saveStore('sotay-v3-builder',state.builder);saveStore('sotay-v3-selected',state.selected);saveStore('sotay-v3-selected-text',state.selectedText)}
function readBuilder(form){const f=new FormData(form);state.builder=Object.fromEntries(f);state.builder.constraints=f.getAll('constraints');persistBuilder();return state.builder}
function markDirty(){if(!state.output)return;state.dirty=true;saveStore('sotay-v3-dirty',true);const el=document.getElementById('output-status');if(el){el.classList.add('dirty');el.innerHTML=I('info')+'Thông tin đã thay đổi — chọn Tạo lại để cập nhật.'}}
function createPrompt(b){const template=prompts.find(x=>x.id===state.selected);const purpose=purposes[b.purpose||'draft'];const intro=template?`MẪU GỢI Ý BAN ĐẦU\n${state.selectedText||template.text}\n\nHãy áp dụng mẫu trên cho thông tin thực tế dưới đây. Không giữ các giá trị minh họa khi chúng khác bối cảnh giáo viên cung cấp.`:`Bạn hỗ trợ tôi ${purpose.toLowerCase()} cho bài dạy sau. Kết quả chỉ là bản dự thảo để giáo viên kiểm tra.`;return `${intro}\n\nTHÔNG TIN BÀI DẠY\n- Môn: ${b.subject}; lớp ${b.grade}; bài: ${b.lesson}.\n- Yêu cầu cần đạt và nguồn đối chiếu: ${b.goals}\n\nBỐI CẢNH LỚP HỌC THỰC TẾ\n- Đặc điểm học sinh: ${b.studentsProfile||'[giáo viên bổ sung]'}.\n- Năng lực sử dụng tiếng Việt: ${b.vietnamese||'[giáo viên bổ sung]'}.\n- Thiết bị, học liệu hiện có: ${b.materials||'[giáo viên bổ sung]'}.\n- Sĩ số: ${b.classSize} học sinh; thời lượng: ${b.duration} phút.\n- Điều kiện lớp học: ${b.classroom||'[giáo viên bổ sung]'}.\n- Lưu ý thực tế: ${b.constraints.length?b.constraints.join('; '):'[giáo viên bổ sung nếu cần]'}.\n${b.source&&['adapt','review'].includes(b.purpose)?'\nBẢN DỰ THẢO CẦN XỬ LÝ\n'+b.source+'\n':''}\nYÊU CẦU ĐẦU RA\n1. Giữ nguyên yêu cầu cần đạt tôi cung cấp. Nếu thông tin thiếu hoặc mâu thuẫn, hỏi lại hoặc đánh dấu để tôi xác minh; không tự bổ sung yêu cầu bắt buộc.\n2. ${b.purpose==='review'?'Lập bảng chỉ ra nội dung cần kiểm tra, căn cứ, mức chắc chắn và đề xuất sửa.':b.purpose==='adapt'?'Chỉ rõ hoạt động chưa phù hợp và đề xuất thay thế theo học sinh, học liệu, không gian và thời lượng trên.':b.purpose==='materials'?'Tạo học liệu, nhiệm vụ và câu hỏi dùng được với đồ sẵn có; tách nội dung cho học sinh và đáp án/gợi ý dành giáo viên.':'Trình bày mục tiêu, thiết bị/học liệu, các hoạt động và chỗ ghi điều chỉnh sau bài dạy để tôi đối chiếu hướng dẫn chuyên môn.'}\n3. Mỗi hoạt động có thời gian, việc của giáo viên, việc của học sinh và sản phẩm/dấu hiệu quan sát. Phân bổ tổng thời gian trong ${b.duration} phút.\n4. Có hỗ trợ tiếng Việt, gợi ý từng bước hoặc nhiệm vụ mở rộng khi phù hợp. Chỉ dùng thiết bị/học liệu đã có; hỏi tôi trước nếu cần thêm.\n5. Kiểm tra kiến thức, phép tính, đơn vị và đáp án. Nêu rõ thông tin chưa chắc chắn.\n\nGiáo viên chịu trách nhiệm kiểm tra tính chính xác, đối chiếu Chương trình GDPT 2018, Công văn 2345/BGDĐT-GDTH và hướng dẫn tại đơn vị, điều chỉnh rồi quyết định nội dung sử dụng.`}
function fillExample(){state.selected=null;state.selectedText='';state.builder={purpose:'draft',subject:'Toán',grade:3,lesson:'Chu vi hình chữ nhật',goals:'Mục tiêu minh họa để giáo viên đối chiếu: nhận biết đường bao, giải thích cách tính chu vi hình chữ nhật và giải bài toán đơn giản với số đo cùng đơn vị. [Thay bằng yêu cầu cần đạt và nguồn đã xác minh.]',studentsProfile:'28 học sinh có tốc độ hoàn thành nhiệm vụ khác nhau; đã biết đo độ dài và thực hiện phép cộng.',vietnamese:'Một số em cần chỉ dẫn ngắn, thao tác làm mẫu và khung câu khi giải thích cách tính.',materials:'Bảng, phấn, thước, bìa hình chữ nhật, vở học sinh.',classSize:28,duration:35,classroom:'Bàn ghế cố định, tổ chức theo cặp; không có máy chiếu; dùng vật thật ngay tại bàn.',constraints:['Không máy chiếu','Internet yếu'],source:''};persistBuilder();markDirty();render();toast('Đã điền dữ liệu minh họa. Thầy cô kiểm tra và chọn Tạo câu lệnh.')}
function updatePromptResults(){const el=document.getElementById('prompt-results');if(el)el.innerHTML=promptResults()}
function resetFilters(){Object.assign(state,{query:'',subject:'',grade:'',purpose:'',savedOnly:false,pg:1});render()}
function printLesson(l){const w=window.open('','_blank');if(!w){toast('Trình duyệt đang chặn cửa sổ in. Thầy cô có thể tải bản .txt.');return}w.document.write(`<!doctype html><html lang="vi"><meta charset="utf-8"><title>${E(l.title)}</title><style>body{font:14px/1.7 Arial,sans-serif;margin:40px;color:#172448}h1{font-size:23px;line-height:1.4}pre{white-space:pre-wrap;font:inherit}button{padding:10px 20px;margin:10px 0;background:#6254e8;color:white;border:0;border-radius:6px}@media print{button{display:none}body{margin:15mm}}</style><h1>${E(l.title)}</h1><button onclick="window.print()">In / lưu PDF</button><pre>${E(lessonText(l))}</pre></html>`);w.document.close();w.focus()}
document.addEventListener('click',e=>{
if(e.target.closest('#drawer a'))closeMenu();
const embedded=e.target.closest('a[download]');if(embedded&&embedded.getAttribute('href').startsWith('data:')){e.preventDefault();const [meta,raw]=embedded.getAttribute('href').split(',');const bytes=Uint8Array.from(atob(raw),c=>c.charCodeAt(0));const u=URL.createObjectURL(new Blob([bytes],{type:meta.slice(5).split(';')[0]}));const a=document.createElement('a');a.href=u;a.download=embedded.download;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),3000);return}
const save=e.target.closest('[data-save]');if(save){const id=save.dataset.save;const active=state.saved.includes(id);state.saved=active?state.saved.filter(x=>x!==id):[...state.saved,id];saveStore('sotay-v3-saved',state.saved);document.querySelectorAll(`[data-save="${id}"]`).forEach(b=>{b.classList.toggle('saved',!active);b.setAttribute('aria-pressed',String(!active));b.setAttribute('aria-label',(!active?'Bỏ lưu':'Lưu')+' câu lệnh '+id)});if(state.page==='resources')render();else if(state.page==='prompts'&&state.savedOnly)updatePromptResults();toast(active?'Đã bỏ lưu câu lệnh.':'Đã lưu vào góc tài liệu của thầy cô.');return}
const open=e.target.closest('[data-open]');if(open){openPrompt(open.dataset.open);return}
const cp=e.target.closest('[data-copy]');if(cp){const p=prompts.find(x=>x.id===cp.dataset.copy);if(p)copy(p.text);return}
if(e.target.closest('[data-reset-filters]')){resetFilters();return}
const pg=e.target.closest('[data-pg]');if(pg&&!pg.disabled){state.pg=Number(pg.dataset.pg);updatePromptResults();document.getElementById('prompt-results').scrollIntoView({behavior:'smooth',block:'start'});return}
const g=e.target.closest('[data-guide]');if(g&&!g.disabled){state.guide=Math.max(0,Math.min(4,Number(g.dataset.guide)));render();return}
if(e.target.closest('[data-fill-example]')){fillExample();return}
if(e.target.closest('#clear-template')){state.selected=null;state.selectedText='';persistBuilder();document.getElementById('selected-template').innerHTML=selectedTemplateHTML();markDirty();return}
if(e.target.closest('#copy-output'))copy(document.getElementById('builder-output').value);
if(e.target.closest('#download-output'))download('Cau_lenh_ca_nhan_hoa.txt',document.getElementById('builder-output').value);
if(e.target.closest('#download-prompts'))download('Thu_vien_80_cau_lenh_AI.txt',PRODUCT+'\n80 CÂU LỆNH MINH HỌA — CẦN GIÁO VIÊN KIỂM TRA\n\n'+prompts.map((p,i)=>`${i+1}. ${p.title}\n${p.subject} — Lớp ${p.grade} — ${purposes[p.purpose]}\nCách dùng: ${p.howto}\n\n${p.text}`).join('\n\n----------------------\n\n'));
if(e.target.closest('#reset-checklist')){state.checks=Array(7).fill(false);saveStore('sotay-v3-checks',state.checks);render()}
if(e.target.closest('#download-checklist'))download('Kiem_tra_ke_hoach_bai_day.txt',PRODUCT+'\n\nDANH SÁCH GIÁO VIÊN TỰ KIỂM TRA\n\n'+checks.map(([t,d],i)=>`${state.checks[i]?'[x]':'[ ]'} ${t}\n${d}`).join('\n\n')+'\n\nViệc đánh dấu không thay thế thẩm định chuyên môn.');
if(e.target.closest('#reset-lessons')){Object.assign(state,{lessonQuery:'',lessonSubject:'',lessonGrade:''});render()}
const ad=e.target.closest('[data-adapt-lesson]');if(ad){const l=lessons.find(x=>x.id===ad.dataset.adaptLesson);state.selected=null;state.selectedText='';state.builder={purpose:'adapt',subject:l.subject,grade:l.grade,lesson:l.title,goals:l.goals,materials:l.materials.join('; '),duration:l.duration,classSize:28,source:lessonText(l),constraints:[]};persistBuilder();markDirty();go('builder');toast('Đã đưa bài mẫu vào biểu mẫu. Thầy cô bổ sung bối cảnh lớp.');return}
const dl=e.target.closest('[data-download-lesson]');if(dl){const l=lessons.find(x=>x.id===dl.dataset.downloadLesson);download('Ke_hoach_tham_khao_'+l.id+'.txt',lessonText(l))}
const pr=e.target.closest('[data-print-lesson]');if(pr)printLesson(lessons.find(x=>x.id===pr.dataset.printLesson));
const ws=e.target.closest('[data-copy-worksheet]');if(ws)copy(lessons.find(x=>x.id===ws.dataset.copyWorksheet).worksheet);
});
document.addEventListener('input',e=>{if(e.target.dataset.lessonNote){const notes=readStore('sotay-v3-notes',{});notes[e.target.dataset.lessonNote]=e.target.value;saveStore('sotay-v3-notes',notes);}if(e.target.id==='prompt-search'){state.query=e.target.value;state.pg=1;updatePromptResults()}if(e.target.id==='lesson-search'){state.lessonQuery=e.target.value;document.getElementById('lesson-results').innerHTML=lessonResults()}if(e.target.closest('#builder-form')){readBuilder(e.target.closest('form'));markDirty()}if(e.target.id==='builder-output'){state.output=e.target.value;saveStore('sotay-v3-output',state.output)}});
document.addEventListener('change',e=>{const filterKeys={'filter-subject':'subject','filter-grade':'grade','filter-purpose':'purpose'};if(filterKeys[e.target.id]){state[filterKeys[e.target.id]]=e.target.value;state.pg=1;updatePromptResults()}if(e.target.id==='saved-only'){state.savedOnly=e.target.checked;state.pg=1;updatePromptResults()}if(e.target.id==='lesson-subject'||e.target.id==='lesson-grade'){state[e.target.id==='lesson-subject'?'lessonSubject':'lessonGrade']=e.target.value;document.getElementById('lesson-results').innerHTML=lessonResults()}if(e.target.dataset.check!==undefined){state.checks[Number(e.target.dataset.check)]=e.target.checked;saveStore('sotay-v3-checks',state.checks);render()}if(e.target.closest('#builder-form')){if(e.target.id==='subject'){const gs=VALID_GRADES[e.target.value]||[1,2,3,4,5];const ge=document.getElementById('grade');const previous=Number(ge.value);ge.innerHTML=gs.map(g=>`<option value="${g}" ${g===previous?'selected':''}>Lớp ${g}</option>`).join('');}readBuilder(e.target.closest('form'));markDirty();const p=prompts.find(x=>x.id===state.selected);if(p&&(['subject','grade','purpose'].includes(e.target.id))&&(p.subject!==state.builder.subject||String(p.grade)!==String(state.builder.grade)||p.purpose!==state.builder.purpose)){state.selected=null;state.selectedText='';persistBuilder();document.getElementById('selected-template').innerHTML=selectedTemplateHTML()}if(e.target.id==='purpose'){const required=['adapt','review'].includes(e.target.value);document.getElementById('source-field').hidden=!required;document.getElementById('source').required=required;document.getElementById('source').disabled=!required}}});
document.addEventListener('submit',e=>{if(e.target.id==='builder-form'){e.preventDefault();const b=readBuilder(e.target);state.output=createPrompt(b);state.dirty=false;saveStore('sotay-v3-dirty',false);saveStore('sotay-v3-output',state.output);document.getElementById('output-area').innerHTML=outputHTML();toast('Đã tạo câu lệnh theo thông tin lớp học.');if(innerWidth<950)document.querySelector('.output-panel').scrollIntoView({behavior:'smooth',block:'start'})}});
document.getElementById('menu-toggle').addEventListener('click',()=>{const d=document.getElementById('drawer');const open=d.classList.toggle('open');d.inert=!open;document.getElementById('scrim').classList.toggle('visible',open);document.getElementById('menu-toggle').setAttribute('aria-expanded',String(open))});document.getElementById('close-menu').addEventListener('click',closeMenu);document.getElementById('scrim').addEventListener('click',closeMenu);
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});document.querySelector('.skip-link').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView({block:'start'})});
document.getElementById('close-dialog').addEventListener('click',()=>document.getElementById('prompt-dialog').close());document.getElementById('dialog-copy').addEventListener('click',()=>copy(document.getElementById('dialog-text').value));document.getElementById('dialog-personalize').addEventListener('click',()=>{const p=prompts.find(x=>x.id===document.getElementById('prompt-dialog').dataset.prompt);state.selected=p.id;state.selectedText=document.getElementById('dialog-text').value;state.builder={...state.builder,subject:p.subject,grade:p.grade,purpose:p.purpose,source:state.builder.source||''};persistBuilder();state.output=document.getElementById('dialog-text').value;state.dirty=true;saveStore('sotay-v3-dirty',true);saveStore('sotay-v3-output',state.output);document.getElementById('prompt-dialog').close();go('builder')});
document.getElementById('prompt-dialog').addEventListener('click',e=>{if(e.target.id==='prompt-dialog'){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
window.addEventListener('research-config-changed',()=>{PRODUCT=window.RESEARCH_CONFIG.get().productTitle;window.Handbook.rendered(state.page);document.title=state.page==='home'?PRODUCT:pages[state.page][0]+' — Sổ tay điện tử AI';if(state.page!=='admin')render();});
window.addEventListener('hashchange',route);hydrateIcons();route();
